package dev.shadw.olympia.mobs;

import dev.shadw.olympia.Pegasus;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Pegasus with its own model and texture. Generated by shadw-mod mob. */
public class PegasusRenderer extends MobRenderer<Pegasus, PegasusModel.State, PegasusModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("olympia", "textures/entity/pegasus.png");

	public PegasusRenderer(EntityRendererProvider.Context context) {
		super(context, new PegasusModel(context.bakeLayer(PegasusModel.LAYER)), 0.9F);
	}

	@Override
	public PegasusModel.State createRenderState() {
		return new PegasusModel.State();
	}

	@Override
	public void extractRenderState(Pegasus entity, PegasusModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(PegasusModel.State state) {
		return TEXTURE;
	}
}
